  },
  "high_order_assessment": [
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00145",
          "explanation": "The family fear about tumor wording was visible and actionable.",
          "quote": "我妈一听肿瘤就害怕"
        },
        {
          "event_id": "lite_evt_00152",
          "explanation": "The doctor corrected the misunderstanding in patient-understandable language and integrated it into communication.",
          "quote": "都不等于癌症"
        }
      ],
      "completion": "complete",
      "explanation": "HO1 was completed: the doctor corrected the cancer-equivalence misunderstanding and reframed the finding as a need for CT/report comparison and follow-up, reducing panic and supporting continued care.",
      "ho_id": "HO1",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
